node -e "
const plan = JSON.parse(require('fs').readFileSync('/Users/llnormll/WorkSpace/my-fortune-site/data/research/_plan.json','utf8'));
const fs = require('fs');
let totalPending = 0;
const cats = Object.keys(plan).filter(k => !k.startsWith('_'));
for (const cat of cats.sort()) {
  const symbols = plan[cat] || [];
  const dir = \`/Users/llnormll/WorkSpace/my-fortune-site/data/research/\${cat}\`;
  const existing = fs.existsSync(dir) ? fs.readdirSync(dir).filter(f=>f.endsWith('.json')).map(f=>f.replace('.json','')):[];
  const existingSet = new Set(existing);
  const pending = symbols.filter(s => !existingSet.has(s.slug));
  if (pending.length > 0) {
    console.log(\`\${cat}: \${pending.length} PENDING - \${pending.map(s=>s.slug).join(', ')}\`);
    totalPending += pending.length;
  } else {
    console.log(\`\${cat}: ✅ (\${symbols.length} planned, \${existing.length} files)\`);
  }
}
console.log('\\nTotal pending:', totalPending);
"

