const fs = require('fs');
const path = require('path');
const researchBase = 'data/research';
const contentBase = 'data/content';
const entries = fs.readdirSync(researchBase);
const cats = entries.filter(e => !e.startsWith('_') && !e.endsWith('.json')).sort();
let totalR = 0, totalC = 0, totalPending = 0;
for (const cat of cats) {
  const rDir = path.join(researchBase, cat);
  const cDir = path.join(contentBase, cat);
  const research = fs.existsSync(rDir) ? fs.readdirSync(rDir).filter(f=>f.endsWith('.json')).length : 0;
  const content = fs.existsSync(cDir) ? fs.readdirSync(cDir).filter(f=>f.endsWith('.json')).length : 0;
  const pending = research - content;
  totalR += research; totalC += content; totalPending += Math.max(0, pending);
  if (pending > 0) console.log(\`\${cat}: \${content}/\${research} (pending: \${pending})\`);
  else console.log(\`\${cat}: \${content}/\${research} ✅\`);
}
console.log(\`\\nTOTAL: \${totalC}/\${totalR} content done · \${totalPending} pending\`);
"

