node -e "
const plan = JSON.parse(require('fs').readFileSync('data/research/_plan.json','utf8'));
const fs = require('fs'), path = require('path');
const cats = Object.keys(plan).filter(k=>!k.startsWith('_')).sort();
let allDone = true;
for(const cat of cats){
  const symbols = plan[cat]||[];
  if(symbols.length===0){console.log(cat.padEnd(18)+' (no plan)'); continue;}
  const dir = 'data/research/'+cat;
  const existing = new Set(fs.existsSync(dir)?fs.readdirSync(dir).filter(f=>f.endsWith('.json')).map(f=>f.replace('.json','')):[] );
  const done = symbols.filter(s=>existing.has(s.slug)).length;
  const pending = symbols.filter(s=>!existing.has(s.slug));
  const status = pending.length===0 ? '✅' : '❌';
  if(pending.length>0) allDone=false;
  console.log(status+' '+cat.padEnd(18)+' '+done+'/'+symbols.length+(pending.length?'  missing: '+pending.map(s=>s.slug).join(', '):''));
}
console.log(allDone?'\\n✅ All 10-per-category research complete!':'\\nSome categories still have gaps');
"
